const int maxn = 1e6 + 5;

int a[maxn];
tuple<int, int, int> seg[4 * maxn];
void propagate(int id) {
    auto [a, b, c] = seg[id];
    if(c != 0) {
        auto[x, y, z] = seg[id * 2];
        seg[id * 2] = {x + c, y, z + c};
    }
    if(c != 0) {
        auto [x, y, z] = seg[id * 2 + 1];
        seg[id * 2 + 1] = {x + c, y, z + c};
    }
    seg[id] = {a, b, 0};
}
tuple<int, int, int> merge(tuple<int, int, int> l, tuple<int, int, int> r) {
    auto [a, b, c] = l;
    auto [x, y, z] = r;
    if(a == x) {
        return {a, max(b, y), 0};
    }
    if(a > x) {
        return {a, b, 0};
    }
    return {x, y, 0};
}
void update(int l, int r, int id, int ql, int qr) {
    if(r < ql or qr < l) {
        return;
    }
    if(ql <= l and r <= qr) {
        auto [a, b, c] = seg[id];
        seg[id] = {a + 1, b, c + 1};
        return;
    }
    propagate(id);
    int mid = (l + r) / 2;
    update(l, mid, id * 2, ql, qr);
    update(mid + 1, r, id * 2 + 1, ql, qr);
    seg[id] = merge(seg[id * 2], seg[id * 2 + 1]);
}
tuple<int, int, int> query(int l, int r, int id, int ql, int qr) {
    if(r < ql or qr < l) {
        return {0, 0, 0};
    }
    if(ql <= l and r <= qr) {
        return seg[id];
    }
    propagate(id);
    int mid = (l + r) / 2;
    return merge(query(l, mid, id * 2, ql, qr),query(mid + 1, r, id * 2 + 1, ql, qr));
}
void build(int l, int r, int id) {
    if(l == r) {
        seg[id] = {l, l, 0};
        return;
    }
    int mid = (l + r) / 2;
    build(l, mid, id * 2);
    build(mid + 1, r, id * 2 + 1);
    seg[id] = merge(seg[id * 2], seg[id * 2 + 1]);
}
pair<int, int> ans[maxn];
vector<pair<int, int>> by_r[maxn];
int cnt[maxn];
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    for(int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    build(1, n, 1);
    int q;
    cin >> q;
    for(int i = 1; i <= q; i++) {
        int l, r;
        cin >> l >> r;
        by_r[r].push_back({l, i});
    }
    
    priority_queue<pair<int, int>> pq;
    for(int r = 1; r <= n; r++) {
        cnt[a[r]] = r;
        update(1, n, 1, 1, cnt[a[r] - 1]);
        update(1, n, 1, 1, cnt[a[r] + 1]);
        /*for(int i = 1; i <= n; i++) {
            debug(query(1, n, 1, i ,i));
        }
        cerr << '\n';
        debug(cnt);*/
        for(pair<int, int> i : by_r[r]) {
            pq.push(i);
        }
        while(!pq.empty()) {
            auto [l, i] = pq.top();
            auto [x, y, z] = query(1, n, 1, 1, l);
            debug(l, i, r, x, y, z);
            if(x != r) {
                break;
            } else {
                ans[i] = {y, r};
                pq.pop();
            }
        }
    }
    for(int i = 1; i <= q; i++) {
        cout << ans[i].first << ' ' << ans[i].second << '\n';
    }
}